using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using SportRace.Domain.Entities; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Admin.Results;
public class CreateModel:PageModel { private readonly IHttpClientFactory _factory; [BindProperty] public Result Result{get;set;}=new(){IsFinished=true}; public List<RegistrationOption> Registrations{get;set;}=new(); public CreateModel(IHttpClientFactory factory)=>_factory=factory; public async Task OnGetAsync()=>await Load(); public async Task<IActionResult> OnPostAsync(){var r=await _factory.CreateClient("SportRaceApi1").PostAsJsonAsync("api/results",Result);if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Неуспешно записване. Проверете дали вече няма резултат за тази регистрация.");await Load();return Page();}return RedirectToPage("Index");} private async Task Load()=>Registrations=await _factory.CreateClient("SportRaceApi1").GetFromJsonAsync<List<RegistrationOption>>("api/registrations")??new(); public class RegistrationOption{public int Id{get;set;} public string ParticipantName{get;set;}="";public string EventName{get;set;}="";public string DisciplineName{get;set;}="";}
}
